// SPDX-License-Identifier: MIT
// Original synthetic differential, adapted from the clean tuning work/swdiff harness.
// Separate HIP and native D3D12 devices receive identical generated bytes. FP8 output only: complements
// the FP32-intermediate post test and explicit rounding mutations; it is not universal arithmetic proof.
//   tuned_swin_diff <rocm dir> <native build dir> <swin.co> <seeds> [kernel filter]
// Inputs per seed: FP8 maps with random codes, block / GEMM weights with plausible FP32 header values and FP8 fragments
// whose magnitude range changes with the seed (so the soft cap, the softmax and GELU see several regimes), window
// offsets ox, oy in {0, 2}. Output buffers are pre-filled with the same pattern on both sides.
#include "../../runtime/device.h"

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <random>
#include <string>
#include <vector>

using namespace wgrt;

static std::mt19937 rng;
static float urand(float a, float b) { return a + (b - a) * (float)(rng() >> 8) * (1.0f / 16777216.0f); }
static uint8_t fp8_code(int emax) {  // random sign, exponent field 1 .. emax, random mantissa
  int e = 1 + (int)(rng() % (unsigned)emax), m = (int)(rng() & 7);
  return (uint8_t)((rng() & 0x80) | (e << 3) | m);
}
static bool full_range = false;  // SW_DIFF_FULLRANGE=1: maps get uniformly random bytes (incl. NaN codes 0x7f / 0xff)
static void fill_fp8(std::vector<uint8_t>& v, size_t off, size_t n, int emax) {
  for (size_t i = 0; i < n; ++i) v[off + i] = fp8_code(emax);
}
static void fill_map(std::vector<uint8_t>& v, size_t off, size_t n, int emax) {
  if (!full_range) return fill_fp8(v, off, n, emax);
  for (size_t i = 0; i < n; ++i) v[off + i] = (uint8_t)(rng() >> 13);
}
static void put_f(std::vector<uint8_t>& v, size_t off, float f) { std::memcpy(&v[off], &f, 4); }

struct Layout { int C, HEADS, MLP; size_t G1, G2, BP, B2, B1, BIAS, STREAM, SIZE, TAIL; };
static Layout block_layout(int C, int HEADS, int MLP, int HPU) {
  Layout L{C, HEADS, MLP};
  int KC = C / 16, MT = MLP / 16;
  L.G1 = 16; L.G2 = L.G1 + 4 * C; L.BP = L.G2 + 4 * C; L.B2 = L.BP + 4 * C; L.B1 = L.B2 + 4 * C;
  L.BIAS = L.B1 + 4 * MLP; L.STREAM = L.BIAS + 4 * HEADS * 256;
  size_t head = (size_t)(6 * KC) * 256, mlp = (size_t)2 * KC * HPU * 256;
  L.SIZE = L.STREAM + HEADS * head + (MT / HPU) * mlp;
  L.TAIL = (L.SIZE + 255) / 256 * 256;
  return L;
}

struct Case {
  const char* name;
  int kind;  // 0 block, 1 block + fused expand (CL 128), 2 patch merge, 3 expand
  int C, HEADS, MLP, HPU, CO;  // CO: merge output channels / expand low channels
  int H, W;
};

int main(int argc, char** argv) {
  if (argc < 5) return std::printf("usage: swin_diff <rocm> <dx12 build> <swin.co> <seeds> [filter]\n"), 2;
  const int seeds = std::atoi(argv[4]);
  const char* filter = argc > 5 ? argv[5] : nullptr;
  if (seeds <= 0) return std::printf("seeds must be positive\n"), 2;
  full_range = std::getenv("SW_DIFF_FULLRANGE") && std::atoi(std::getenv("SW_DIFF_FULLRANGE"));
  std::string err;
  auto hip = make_hip_device(argv[1], &err);
  if (!hip) return std::printf("make_hip_device: %s\n", err.c_str()), 1;
  auto dx = make_d3d12_device(argv[2], &err);
  if (!dx) return std::printf("make_d3d12_device: %s\n", err.c_str()), 1;
  if (!hip->load_module(argv[3]) || !dx->load_module(argv[3]))
    return std::printf("load: hip=%s native=%s\n", hip->err().c_str(), dx->err().c_str()), 1;
  std::vector<Case> cases = {
      {"swin_block_c64_nc", 0, 64, 2, 256, 8, 0, 480, 864},
      {"swin_block_c96_nc", 0, 96, 4, 384, 4, 0, 240, 432},
      {"swin_block_c96_add_ex_nc", 1, 96, 4, 384, 4, 128, 240, 432},
      {"patch_merge_c64", 2, 64, 0, 0, 0, 96, 480, 864},
      {"patch_merge_c96", 2, 96, 0, 0, 0, 128, 240, 432},
      {"expand_c96", 3, 64, 0, 0, 0, 96, 240, 432},  // C = 64 output channels, CO = 96 low-resolution channels
  };
  long long total_bad = 0;
  int executed = 0;
  for (const Case& c : cases) {
    if (filter && !std::strstr(c.name, filter)) continue;
    ++executed;
    long long bad = 0, compared = 0;
    for (int s = 0; s < seeds; ++s) {
      rng.seed(1000u * (unsigned)s + 17u);
      const int ox = (s & 1) * 2, oy = (s & 2);
      const int emax_w = 3 + s % 4, emax_x = 5 + s % 3;  // fragment magnitudes up to 2^(emax - 7) * 1.875
      std::vector<std::vector<uint8_t>> bufs;
      std::vector<int> ints;
      unsigned grid = 0;
      int out_index = 0;
      std::string kname = c.name;
      if (c.kind <= 1) {
        const Layout L = block_layout(c.C, c.HEADS, c.MLP, c.HPU);
        const size_t map = (size_t)c.H * c.W * c.C;
        std::vector<uint8_t> x(c.kind == 1 ? (size_t)(c.H / 2) * (c.W / 2) * c.CO : map), xadd(c.kind == 1 ? map : 0),
            out(map), w(L.TAIL + (c.kind == 1 ? 16 * c.C + (size_t)4 * (c.C / 16) * (c.CO / 16) * 256 : 0));
        fill_map(x, 0, x.size(), emax_x);
        if (!xadd.empty()) fill_map(xadd, 0, xadd.size(), emax_x);
        for (auto& b : out) b = 0x5a;
        std::memset(w.data(), 0, w.size());
        put_f(w, 0, 1.0f);
        for (int i = 0; i < c.C; ++i) {
          put_f(w, L.G1 + 4 * i, urand(0.25f, 2.0f));
          put_f(w, L.G2 + 4 * i, urand(0.25f, 2.0f));
          put_f(w, L.BP + 4 * i, urand(-1.0f, 1.0f));
          put_f(w, L.B2 + 4 * i, urand(-1.0f, 1.0f));
        }
        for (int i = 0; i < c.MLP; ++i) put_f(w, L.B1 + 4 * i, urand(-2.0f, 2.0f));
        for (int i = 0; i < c.HEADS * 256; ++i) put_f(w, L.BIAS + 4 * i, urand(-12.0f, 12.0f));
        fill_fp8(w, L.STREAM, L.SIZE - L.STREAM, emax_w);
        if (c.kind == 1) {
          for (int i = 0; i < 4 * c.C; ++i) put_f(w, L.TAIL + 4 * i, urand(-1.0f, 1.0f));
          fill_fp8(w, L.TAIL + 16 * c.C, w.size() - L.TAIL - 16 * c.C, emax_w);
        }
        bufs = {x, xadd, out, w};
        ints = {c.H, c.W, ox, oy};
        grid = (unsigned)((((c.W + ox + 3) / 4) * ((c.H + oy + 3) / 4) + 7) / 8);
        out_index = 2;
      } else if (c.kind == 2) {
        const int KZ = c.C / 4, MO = c.CO / 16;
        std::vector<uint8_t> sm((size_t)c.H * c.W * c.C), out((size_t)(c.H / 2) * (c.W / 2) * c.CO),
            w(4 * c.CO + (size_t)MO * KZ * 256);
        fill_map(sm, 0, sm.size(), emax_x);
        for (auto& b : out) b = 0x5a;
        for (int i = 0; i < c.CO; ++i) put_f(w, 4 * i, urand(-1.0f, 1.0f));
        fill_fp8(w, 4 * c.CO, w.size() - 4 * c.CO, emax_w);
        bufs = {sm, out, w};
        ints = {c.H, c.W};
        grid = (unsigned)(((c.H / 2) * (c.W / 2) + 255) / 256);
        out_index = 1;
      } else {
        const int KC = c.CO / 16, G = c.C / 16;
        std::vector<uint8_t> y((size_t)c.H * c.W * c.CO), e((size_t)4 * c.H * c.W * c.C),
            w(16 * c.C + (size_t)4 * G * KC * 256);
        fill_map(y, 0, y.size(), emax_x);
        for (auto& b : e) b = 0x5a;
        for (int i = 0; i < 4 * c.C; ++i) put_f(w, 4 * i, urand(-1.0f, 1.0f));
        fill_fp8(w, 16 * c.C, w.size() - 16 * c.C, emax_w);
        bufs = {y, e, w};
        ints = {c.H, c.W};
        grid = (unsigned)((c.H * c.W + 255) / 256);
        out_index = 1;
      }
      // two copies of every buffer: one for each side
      std::vector<DevPtr> ph, pd;
      for (auto& b : bufs) {
        DevPtr a = 0, d = 0;
        if (!b.empty()) {
          if (!hip->alloc(&a, b.size()) || !dx->alloc(&d, b.size()) ||
              !hip->upload(a, b.data(), b.size()) || !dx->upload(d, b.data(), b.size()))
            return std::printf("allocation/upload: hip=%s native=%s\n", hip->err().c_str(), dx->err().c_str()), 1;
        }
        ph.push_back(a), pd.push_back(d);
      }
      DevPtr nul = 0;
      auto launch = [&](Device& dev, const std::string& k, std::vector<DevPtr>& p) {
        std::vector<void*> args;
        for (auto& q : p) args.push_back(&q);
        for (auto& i : ints) args.push_back(&i);
        if (c.kind == 1) args.push_back(&nul);
        return dev.launch(k, grid, 256, args.data());
      };
      if (!launch(*hip, kname, ph) || !launch(*dx, kname, pd))
        return std::printf("%s: hip=%s native=%s\n", c.name, hip->err().c_str(), dx->err().c_str()), 1;
      const size_t n = bufs[out_index].size();
      std::vector<uint8_t> a(n), b(n);
      if (!hip->download(a.data(), ph[out_index], n) || !dx->download(b.data(), pd[out_index], n))
        return std::printf("download: hip=%s native=%s\n", hip->err().c_str(), dx->err().c_str()), 1;
      long long nb = 0, first = -1;
      for (size_t i = 0; i < n; ++i)
        if (a[i] != b[i]) { if (first < 0) first = (long long)i; ++nb; }
      size_t unwritten = 0;
      for (size_t i = 0; i < n; ++i) unwritten += a[i] == 0x5a;
      if (nb) std::printf("  %s seed %d (ox %d oy %d): %lld differing bytes, first at %lld (hip %02x d3d12 %02x)\n", c.name, s,
                          ox, oy, nb, first, a[first], b[first]);
      bad += nb;
      compared += (long long)n;
      {
        size_t hist[256] = {0};
        for (size_t i = 0; i < n; ++i) ++hist[a[i]];
        int distinct = 0;
        for (int v = 0; v < 256; ++v) distinct += hist[v] != 0;
        std::printf("  %s seed %d: %zu bytes, fill %.2f %%, NaN %.2f %%, +-448 %.2f %%, zero %.2f %%, %d distinct codes\n",
                    c.name, s, n, 100.0 * unwritten / n, 100.0 * (hist[0x7f] + hist[0xff]) / n,
                    100.0 * (hist[0x7e] + hist[0xfe]) / n, 100.0 * (hist[0] + hist[0x80]) / n, distinct);
      }
      for (auto& q : ph) if (q) hip->free(q);
      for (auto& q : pd) if (q) dx->free(q);
    }
    std::printf("%-28s %d seeds: %lld differing of %lld bytes\n", c.name, seeds, bad, compared);
    total_bad += bad;
  }
  if (!executed) return std::printf("no matching kernels\n"), 2;
  std::printf("swin_diff: %s\n", total_bad ? "DIFFERENT" : "IDENTICAL");
  return total_bad ? 3 : 0;
}
